fn capitalize_first_letter(word: Vec<char>) -> Vec<char> 
    //@ requires word.len() >= 1
    //@ ensures result.len() == word.len()
    //@ ensures word.len() == 0 ==> result.len() == 0
    //@ ensures (word[0].is_ascii_uppercase()) ==> result[0] == word[0]
    //@ ensures (!word[0].is_ascii_uppercase()) ==> result[0] == 'A'
    //@ ensures forall(|i: usize| 1 <= i && i < word.len() ==> result[i] == word[i])
{
    if word.is_empty() {
        // Problem states input is non-empty, but handle just in case
        return word;
    }

    let mut result = Vec::with_capacity(word.len());

    let first_char = word[0];
    if first_char.is_ascii_uppercase() {
        // If first char already uppercase, keep it
        result.push(first_char);
    } else {
        // If first char lowercase, replace with 'A'
        result.push('A');
    }

    // Append the rest of the characters unchanged
    result.extend_from_slice(&word[1..]);

    result
}